// Synthetic-only preparation. Replace with an approved scheduling adapter at deployment time.
const profile = {
  business: { name: 'Sunrise Dental Clinic (DEMO)', hours: 'Mon-Sat, 9am-7pm IST', handover_contact: '+919000000000' },
  modules: { booking: true, lead_capture: true, order_status: false, payment_link: false }
};
const request = {
  name: 'Priya (demo)',
  contact: '+919000000002',
  text: 'Kal ka slot milega kya?',
  requested_window: 'tomorrow_morning',
  consent_status: 'granted',
  channel: 'whatsapp_demo',
  correlation_id: 'DEMO-UR-BOOKING-001'
};
// Slots MUST come from the client-owned scheduling source; the demo list is fictional and never sent anywhere.
const source_availability = [
  { slot_id: 'SLOT-001', date: '2026-01-16', start: '10:00', service: 'Consultation', provider: 'Dr. Demo' },
  { slot_id: 'SLOT-002', date: '2026-01-16', start: '11:30', service: 'Consultation', provider: 'Dr. Demo' },
  { slot_id: 'SLOT-003', date: '2026-01-16', start: '14:00', service: 'Cleaning', provider: 'Dr. Demo' }
];
const correlation_id = request.correlation_id || 'DEMO-UNIVERSAL-REPLIER-BOOKING-SAMPLE';
return [{ json: { ...request, profile, source_availability, correlation_id, _demo: true, _scenario: 'replier-booking' } }];

const d = $input.first().json;
const modules = (d.profile && d.profile.modules) || {};
const slots = Array.isArray(d.source_availability) ? d.source_availability : [];
const missing = ['name', 'contact', 'text'].filter((key) => !String(d[key] || '').trim());
const bookingEnabled = modules.booking === true;
const slotsConfirmed = slots.length > 0 && slots.every((s) => s.slot_id && s.date && s.start);
const review = missing.length > 0 || !bookingEnabled || !slotsConfirmed || d.consent_status !== 'granted';
return [{ json: { ...d, _validation: { status: review ? 'NEEDS_HUMAN_REVIEW' : 'READY', review_required: review, missing, reason: missing.length ? 'Required booking data is missing' : !bookingEnabled ? 'Booking module is switched off in the profile' : !slotsConfirmed ? 'Availability list empty or unconfirmed by the scheduling source' : d.consent_status !== 'granted' ? 'Consent is not confirmed' : 'Booking request validated' } } }];

const d = $input.first().json;
const v = d._validation || { status: 'NEEDS_HUMAN_REVIEW', review_required: true, reason: 'Validation output missing' };
const slots = Array.isArray(d.source_availability) ? d.source_availability : [];
const offered = slots.slice(0, 3).map((s) => s.slot_id + ' ' + s.date + ' ' + s.start + ' (' + (s.service || 'service') + ')');
const booking_draft = {
  module: 'booking',
  offered_slots: v.status === 'READY' ? offered : [],
  confirmation_draft: v.status === 'READY'
    ? 'Draft only: Hello ' + (d.name || '') + ', these slots are open tomorrow: ' + offered.join(', ') + '. Reply with a slot and the team will confirm.'
    : '',
  calendar_write: 'not_performed_in_demo',
  reminder_after_booking: 'Send an opted-in reminder from the approved template only.'
};
const correlation_id = d.correlation_id || 'DEMO-UNKNOWN';
const audit = { workflow: 'replier-booking', action: 'draft_only', record_id: d.contact || 'sample', correlation_id: correlation_id };
return [{ json: { ...d, status: v.status === 'READY' ? 'DRAFT_ONLY' : 'NEEDS_HUMAN_REVIEW', review_required: v.review_required, reason: v.reason, needs_human: v.review_required, booking_draft: booking_draft, action_draft: { reply: booking_draft.confirmation_draft || 'Route the booking request to a human owner; never invent slots.', owner: v.review_required ? 'human-review' : 'replier' }, audit } }];
